@using System.Threading
@inject IProductService ProductService
@implements IDisposable

<div class="product-search">
    <input type="text"
           placeholder="Search products…"
           @oninput="OnSearchInput"
           value="@_query" />

    @if (_loading)
    {
        <div class="product-search-status">Searching…</div>
    }
    else if (_error is not null)
    {
        <div class="product-search-status product-search-error">
            Something went wrong. Please try again.
        </div>
    }
    else if (_searched && _results.Count == 0)
    {
        <div class="product-search-status">No products found.</div>
    }

    @if (_results.Count > 0)
    {
        <div class="product-search-results">
            @foreach (var product in _results)
            {
                <div class="product-card" @onclick="() => SelectProduct(product)">
                    <img src="@product.ImageUrl" alt="@product.Name" loading="lazy" />
                    <h3>@product.Name</h3>
                    <p class="product-card-price">@product.Price.ToString("C")</p>
                </div>
            }
        </div>
    }
</div>

@code {
    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    private string _query = string.Empty;
    private List<Product> _results = new();
    private bool _loading;
    private bool _searched;
    private Exception? _error;

    private CancellationTokenSource? _debounceTokenSource;
    private CancellationTokenSource? _searchTokenSource;

    private async Task OnSearchInput(ChangeEventArgs e)
    {
        _query = e.Value?.ToString() ?? string.Empty;

        // Cancel any pending debounce timer and any in-flight search.
        CancelDebounce();

        if (string.IsNullOrWhiteSpace(_query))
        {
            ResetState();
            return;
        }

        _debounceTokenSource = new CancellationTokenSource();
        var debounceToken = _debounceTokenSource.Token;

        try
        {
            await Task.Delay(300, debounceToken);
        }
        catch (TaskCanceledException)
        {
            // User typed again before the debounce elapsed — nothing to do.
            return;
        }

        await ExecuteSearchAsync(_query);
    }

    private async Task ExecuteSearchAsync(string query)
    {
        // Cancel any previous search that is still running.
        CancelSearch();

        _searchTokenSource = new CancellationTokenSource();
        var searchToken = _searchTokenSource.Token;

        _loading = true;
        _error = null;

        try
        {
            var results = await ProductService.SearchAsync(query, searchToken);

            if (searchToken.IsCancellationRequested)
                return;

            _results = results;
            _searched = true;
        }
        catch (OperationCanceledException)
        {
            // Search was superseded by a newer query — discard silently.
        }
        catch (Exception ex)
        {
            if (!searchToken.IsCancellationRequested)
            {
                _error = ex;
                _results = new();
            }
        }
        finally
        {
            if (!searchToken.IsCancellationRequested)
            {
                _loading = false;
            }
        }
    }

    private async Task SelectProduct(Product product)
    {
        await OnProductSelected.InvokeAsync(product);
    }

    private void ResetState()
    {
        CancelSearch();
        _results = new();
        _loading = false;
        _searched = false;
        _error = null;
    }

    private void CancelDebounce()
    {
        _debounceTokenSource?.Cancel();
        _debounceTokenSource?.Dispose();
        _debounceTokenSource = null;
    }

    private void CancelSearch()
    {
        _searchTokenSource?.Cancel();
        _searchTokenSource?.Dispose();
        _searchTokenSource = null;
    }

    public void Dispose()
    {
        CancelDebounce();
        CancelSearch();
    }
}

